#!/usr/bin/env node
/**
 * Rebuild demigod-pages/*.html from embedded specs (map4 brand shell).
 * Usage: node demigod-pages-build.mjs
 * Then upload: for f in demigod-pages/*.html; do curl -F reqtype=fileupload -F fileToUpload=@$f https://catbox.moe/user/api.php; done
 */
import { spawnSync } from 'child_process';
import path from 'path';
import { fileURLToPath } from 'url';
const root = path.dirname(fileURLToPath(import.meta.url));
// pages are already generated by last python pass; this re-runs if generator exists
const py = path.join(root, 'scripts/demigod-pages-gen.py');
const r = spawnSync('python3', [py], { cwd: root, encoding: 'utf8' });
if (r.status !== 0) {
  console.error(r.stderr || r.stdout || 'missing scripts/demigod-pages-gen.py — pages already on disk');
  process.exit(r.status || 1);
}
console.log(r.stdout);
